const products=seeds.map((s,i)=>({id:i,name:s[0],sku:s[1],market:s[2],category:s[3],price:s[4],unitCost:s[5],base:s[6],stock:s[7],incoming:i%4===0?100:i%5===0?60:0,warehouse:s[2]==='wb'?(i%3?'Коледино':'Казань'):(i%3?'Софьино':'Хоругвино'),owner:people[i%4],rating:4.5+(i%5)/10}));
const end=Date.UTC(2026,8,16),dayMs=86400000;const history=Array.from({length:60},(_,d)=>({date:new Date(end-(59-d)*dayMs),items:products.map((p,i)=>{const wave=1+Math.sin((d+i)*.65)*.19+(d%7===5?.14:0),growth=.82+d*.006,orders=Math.max(1,Math.round(p.base*wave*growth)),cancel=Math.floor(orders*(.05+i%3*.02)+(d%10)/10),paid=orders-cancel,returns=Math.min(paid,Math.floor(paid*(.03+i%4*.018)+((d*3+i)%10)/10)),sold=paid-returns,revenue=sold*p.price,purchase=sold*p.unitCost,commission=Math.round(revenue*(p.market==='wb'?.21:.19)),logistics=paid*(75+i%4*20)+returns*55,storage=25+i*3,adRevenue=Math.round(revenue*(.24+i%4*.07)),adRate=i===1?.24:i===8?.31:i===17?.27:.09+i%5*.018,ads=Math.round(adRevenue*adRate),tax=Math.round(revenue*.06),visits=orders*(19+i%6*4),clicks=Math.max(1,Math.round(ads/(11+i%5*3))),impressions=clicks*(27+i%7*3),profit=revenue-purchase-commission-logistics-storage-ads-tax;return{id:i,orders,cancel,paid,returns,sold,revenue,purchase,commission,logistics,storage,adRevenue,ads,tax,visits,clicks,impressions,profit};})}));
