let market='all',period=30,page=1;const $=id=>document.getElementById(id),selectedProducts=()=>products.filter(p=>market==='all'||p.market===market),dateLabel=d=>d.toLocaleDateString('ru-RU',{day:'numeric',month:'short',timeZone:'UTC'}),isLate=t=>!t.done&&t.due<'2026-09-16';
function aggregate(p,days){return {...p,...sum(days.map(d=>d.items[p.id]))}}
function inventory(p){const avg=sum(history.slice(-7).map(d=>d.items[p.id])).sold/7,cover=avg?p.stock/avg:0;return{avg,cover,reorder:Math.max(0,Math.ceil(avg*21-p.stock-p.incoming))}}
function rows(previous=false){const days=previous?history.slice(60-period*2,60-period):history.slice(-period);return selectedProducts().map(p=>({...aggregate(p,days),...inventory(p)}))}
function filtered(){const q=$('search').value.toLowerCase().trim(),cat=$('category').value,risk=$('risk').value;return rows().filter(p=>(p.name+' '+p.sku).toLowerCase().includes(q)&&(cat==='all'||p.category===cat)&&(risk==='all'||risk==='low'&&p.cover<7||risk==='loss'&&p.profit<0||risk==='ads'&&ratio(p.ads,p.adRevenue)>15)).sort((a,b)=>$('sort').value==='profit'?b.profit-a.profit:$('sort').value==='margin'?ratio(a.profit,a.revenue)-ratio(b.profit,b.revenue):$('sort').value==='stock'?a.cover-b.cover:b.revenue-a.revenue)}
function delta(v,old,inverse=false){if(!old)return '<span>Нет базы сравнения</span>';const n=(v-old)/Math.abs(old)*100;return `<span class="${(inverse?n<0:n>=0)?'up':'down'}">${n>=0?'+':''}${pct(n)}</span> к предыдущему периоду`}
function card(l,v,sub,featured=false){return `<article class="metric ${featured?'featured':''}"><div class="label">${l}</div><div class="value">${v}</div><div class="sub">${sub}</div></article>`}
function render(){const a=sum(rows()),b=sum(rows(true));$('metrics').innerHTML=card('Выручка после возвратов',money(a.revenue),delta(a.revenue,b.revenue),true)+card('Прибыль по товарам',money(a.profit),delta(a.profit,b.profit))+card('Заказы',fmt(a.orders),delta(a.orders,b.orders))+card('Маржа',pct(ratio(a.profit,a.revenue)),'Прибыль / выручка')+card('Реклама',money(a.ads),delta(a.ads,b.ads,true))+card('ДРР рекламных продаж',pct(ratio(a.ads,a.adRevenue)),'Реклама / рекламная выручка')+card('Возвраты',fmt(a.returns),pct(ratio(a.returns,a.paid))+' оплаченных товаров')+card('Средний чек',money(a.revenue/a.sold),'Выручка / товары без возврата');renderChart();renderFinance(a);renderProducts();renderAds(a);renderInventory();renderTasks();attention();}
function renderChart(){const days=history.slice(-period),ids=selectedProducts().map(p=>p.id),values=days.map(d=>sum(ids.map(id=>d.items[id])).revenue),revenue=values.reduce((a,b)=>a+b,0),plan=selectedProducts().reduce((a,p)=>a+p.base*p.price*.99,0)*period;$('plan').textContent=money(plan);$('plan-percent').textContent=pct(ratio(revenue,plan))+' выполнено';$('plan-bar').style.width=Math.min(100,ratio(revenue,plan))+'%';const max=Math.max(...values)*1.15,w=650,h=230,left=60,right=15,top=15,bottom=35,plot=h-top-bottom,pts=values.map((v,i)=>[left+i*(w-left-right)/(values.length-1),top+plot*(1-v/max)]),path=pts.map((p,i)=>(i?'L':'M')+p.join(',')).join(' ');$('chart').setAttribute('aria-label',`Выручка за ${period} дней: ${money(revenue)}`);$('chart').innerHTML=`<svg class="chart" viewBox="0 0 ${w} ${h}" aria-hidden="true"><defs><linearGradient id="fill" x2="0" y2="1"><stop stop-color="#3662e9" stop-opacity=".2"/><stop offset="1" stop-color="#3662e9" stop-opacity="0"/></linearGradient></defs>${[0,1,2,3].map(i=>{const y=top+plot*i/3;return `<line x1="${left}" y1="${y}" x2="${w-right}" y2="${y}" stroke="#e7edf7" stroke-dasharray="4 4"/><text x="0" y="${y+4}">${fmt(max*(1-i/3)/1000)} тыс.</text>`}).join('')}<path d="${path} L${w-right},${h-bottom} L${left},${h-bottom} Z" fill="url(#fill)"/><path d="${path}" fill="none" stroke="#3662e9" stroke-width="2.5"/>${pts.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="3" fill="white" stroke="#3662e9"><title>${dateLabel(days[i].date)}: ${money(values[i])}</title></circle>`).join('')}${[0,Math.floor((period-1)/3),Math.floor(2*(period-1)/3),period-1].map(i=>`<text x="${pts[i][0]}" y="${h-5}" text-anchor="${i===0?'start':i===period-1?'end':'middle'}">${dateLabel(days[i].date)}</text>`).join('')}</svg>`;}
const costLabels=[['purchase','Себестоимость'],['commission','Комиссии площадок'],['logistics','Логистика и возвраты'],['ads','Реклама'],['storage','Хранение'],['tax','Условный налог · 6%']];
function financeMarkup(a){return `<div class="finance-row total"><span>Выручка после возвратов</span><strong>${money(a.revenue)}</strong></div>${costLabels.map(([k,l])=>`<div class="finance-row"><div><span>${l}</span><div class="cost-track"><div style="width:${Math.min(100,ratio(a[k],a.revenue))}%"></div></div></div><span class="cost-percent">${pct(ratio(a[k],a.revenue))}</span><strong>−${money(a[k])}</strong></div>`).join('')}<div class="finance-row total ${a.profit<0?'loss':'profit'}"><span>Прибыль по товарам</span><strong>${money(a.profit)}</strong></div>`}
function renderFinance(a){$('finance-rows').innerHTML=financeMarkup(a);$('funnel').innerHTML=[['Посещения карточек',a.visits],['Оформленные заказы',a.orders],['Оплаченные товары',a.paid],['Без возврата',a.sold]].map(([l,n],i,arr)=>`<div class="funnel-row"><span class="funnel-step">${i+1}</span><div><span>${l}</span><div class="funnel-track"><div style="width:${i===0?100:ratio(n,arr[i-1][1])}%"></div></div></div><strong>${fmt(n)}</strong><small>${i?pct(ratio(n,arr[i-1][1]))+' от этапа выше':'100% трафика'}</small></div>`).join('');$('market-comparison').innerHTML=`<h3>Площадки: выручка / прибыль</h3>${['wb','ozon'].filter(m=>market==='all'||market===m).map(m=>{const s=sum(rows().filter(p=>p.market===m));return `<div><span class="market-pill ${m}">${m==='wb'?'Wildberries':'Ozon'}</span><strong>${money(s.revenue)}</strong><span>${money(s.profit)}</span></div>`}).join('')}<p>Отмены: ${fmt(a.cancel)} · Конверсия в заказ: ${pct(ratio(a.orders,a.visits))}</p>`;}
function renderProducts(){const all=filtered(),pages=Math.max(1,Math.ceil(all.length/8));page=Math.min(page,pages);$('product-rows').innerHTML=all.slice((page-1)*8,page*8).map(p=>`<tr><td><span class="product-icon" aria-hidden="true">▦</span><span class="product-name"><button class="text-button" data-detail="${p.id}">${p.name}</button><small>${p.sku} · ${p.category}</small></span></td><td><span class="market-pill ${p.market}">${p.market==='wb'?'Wildberries':'Ozon'}</span></td><td><strong>${money(p.revenue)}</strong></td><td class="${p.profit<0?'loss-text':''}">${money(p.profit)}</td><td>${pct(ratio(p.profit,p.revenue))}</td><td>${fmt(p.orders)}</td><td>${fmt(p.returns)}</td><td class="${ratio(p.ads,p.adRevenue)>15?'loss-text':''}">${pct(ratio(p.ads,p.adRevenue))}</td><td><span class="stock ${p.cover<7?'low':''}">${Math.floor(p.cover)} дн.</span></td></tr>`).join('')||'<tr><td colspan="9">Товары не найдены. Измените поиск или фильтры.</td></tr>';$('product-count').textContent=`Найдено ${all.length} из ${rows().length} товаров · Нажмите название для деталей`;$('page-label').textContent=`${page} / ${pages}`;$('prev').disabled=page===1;$('next').disabled=page===pages;}
function mini(items){return items.map(([l,v])=>`<div><span>${l}</span><strong>${v}</strong></div>`).join('')}
function renderAds(a){$('ad-metrics').innerHTML=mini([['Расходы',money(a.ads)],['Рекламная выручка',money(a.adRevenue)],['CTR · клики / показы',pct(ratio(a.clicks,a.impressions))],['CPC · цена клика',money(a.ads/a.clicks)]]);$('ad-rows').innerHTML=rows().sort((a,b)=>b.ads-a.ads).slice(0,8).map(p=>`<tr><td><span class="product-name">${p.name}<small>${p.market==='wb'?'WB · Поиск':'Ozon · Продвижение'}</small></span></td><td>${money(p.ads)}</td><td>${fmt(p.impressions)}</td><td>${fmt(p.clicks)}</td><td>${pct(ratio(p.clicks,p.impressions))}</td><td>${money(p.ads/p.clicks)}</td><td>${money(p.adRevenue)}</td><td><span class="stock ${ratio(p.ads,p.adRevenue)>15?'low':''}">${pct(ratio(p.ads,p.adRevenue))}</span></td></tr>`).join('');if(!$('ad-note'))$('ads').insertAdjacentHTML('beforeend','<p class="section-note" id="ad-note">8 кампаний с наибольшими расходами. Итоги выше учитывают все кампании выбранной площадки.</p>');}
function renderInventory(){const data=rows();$('stock-metrics').innerHTML=mini([['На складах',fmt(data.reduce((s,p)=>s+p.stock,0))+' шт.'],['В пути',fmt(data.reduce((s,p)=>s+p.incoming,0))+' шт.'],['Запас менее 7 дней',String(data.filter(p=>p.cover<7).length)+' товаров'],['Стоимость остатков',money(data.reduce((s,p)=>s+p.stock*p.unitCost,0))]]);$('stock-rows').innerHTML=data.sort((a,b)=>a.cover-b.cover).slice(0,8).map(p=>`<tr><td>${p.name}</td><td>${p.warehouse}</td><td>${fmt(p.stock)}</td><td>${fmt(p.incoming)}</td><td><span class="stock ${p.cover<7?'low':''}">${Math.floor(p.cover)}</span></td><td><strong>${fmt(p.reorder)}</strong></td><td>${p.owner}</td></tr>`).join('')}
function attention(){const data=rows(),low=data.filter(p=>p.cover<7).length,late=tasks.filter(isLate).length,bad=data.filter(p=>ratio(p.ads,p.adRevenue)>15).length;document.querySelector('.attention .count').textContent=String((low>0)+(late>0)+(bad>0));const links=document.querySelectorAll('.attention>a');links[0].style.display=low?'flex':'none';links[0].querySelector('p').textContent=`Товаров с запасом менее 7 дней: ${low}`;links[0].href='#inventory';links[1].style.display=late?'flex':'none';links[1].querySelector('p').textContent=`Просроченных задач: ${late}`;document.querySelector('.attention-item').style.display=bad?'flex':'none';document.querySelector('.attention-item p').textContent=`Кампаний с ДРР выше 15%: ${bad}`;document.querySelector('.insight').innerHTML=`Убыточные позиции<span>${data.filter(p=>p.profit<0).length} из ${data.length} товаров. Выберите фильтр «Убыточные» в экономике товаров, чтобы разобрать расходы.</span>`;}
function renderTasks(){const done=tasks.filter(t=>t.done).length;$('team-cards').innerHTML=people.map((name,i)=>{const list=tasks.filter(t=>t.person===name),n=list.filter(t=>t.done).length;return `<article><div class="team-person"><span class="avatar">${name.split(' ').map(w=>w[0]).join('')}</span><div><strong>${name}</strong><small>${roles[i]}</small></div></div><div class="team-result"><b>${n} / ${list.length}</b><span>задач выполнено</span></div><div class="team-progress"><div style="width:${ratio(n,list.length)}%"></div></div><p>${list.filter(isLate).length} просрочено · ${list.filter(t=>!t.done).length} в работе</p></article>`}).join('');const status=$('task-status').value,assignee=$('assignee').value,list=tasks.filter(t=>(assignee==='all'||assignee===t.person)&&(status==='all'||status==='done'&&t.done||status==='open'&&!t.done||status==='late'&&isLate(t)));$('task-list').innerHTML=list.map(t=>`<div class="task ${t.done?'done':''}"><input type="checkbox" id="task-${t.id}" data-task="${t.id}" ${t.done?'checked':''} aria-label="Выполнено: ${t.title}"><label class="task-title" for="task-${t.id}">${t.title}<small>${t.category}</small></label><span class="person">${t.person}</span><span class="due ${isLate(t)?'late':''}">${t.done?'Выполнено':dateLabel(new Date(t.due+'T00:00:00Z'))}${isLate(t)?'<small>Просрочено</small>':''}</span></div>`).join('')||'<p class="section-note">Нет задач с такими условиями.</p>';$('task-summary').textContent=`Показано ${list.length} из ${tasks.length} задач · Всего выполнено ${done} · Команда не зависит от фильтра площадки и периода · Изменения до перезагрузки`;attention();}
function openProduct(id){const p=rows().find(p=>p.id===id);if(!p)return;$('detail-title').textContent=p.name;$('detail-subtitle').textContent=`${p.sku} · ${p.market==='wb'?'Wildberries':'Ozon'} · последние ${period} дней`;$('detail-content').innerHTML=`<div class="mini-metrics">${mini([['Цена',money(p.price)],['Продано без возврата',fmt(p.sold)],['Прибыль на единицу',money(p.profit/p.sold)],['Рейтинг · демо',p.rating.toFixed(1)]])}</div>${financeMarkup(p)}<div class="detail-supply"><h3>Поставка и ответственный</h3><p>${p.warehouse}: ${p.stock} шт. · В пути: ${p.incoming} шт. · Запас: ${Math.floor(p.cover)} дн.</p><p>Рекомендуемая поставка: <strong>${p.reorder} шт.</strong> на 21 день продаж.</p><p>Ответственный: ${p.owner}</p></div>`;$('product-dialog').showModal()}
document.querySelectorAll('[data-market]').forEach(b=>b.addEventListener('click',()=>{market=b.dataset.market;page=1;document.querySelectorAll('[data-market]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))});render()}));$('period').addEventListener('change',e=>{period=Number(e.target.value);page=1;render()});['search','category','risk','sort'].forEach(id=>$(id).addEventListener(id==='search'?'input':'change',()=>{page=1;renderProducts()}));$('prev').onclick=()=>{page--;renderProducts()};$('next').onclick=()=>{page++;renderProducts()};$('product-rows').onclick=e=>{const b=e.target.closest('[data-detail]');if(b)openProduct(Number(b.dataset.detail))};$('close-detail').onclick=()=>$('product-dialog').close();['assignee','task-status'].forEach(id=>$(id).onchange=renderTasks);$('task-list').onchange=e=>{if(e.target.dataset.task!==undefined){tasks[Number(e.target.dataset.task)].done=e.target.checked;renderTasks()}};
$('export').onclick=()=>{const start=history[60-period].date,all=filtered(),data=[['ДЕМОНСТРАЦИОННЫЕ ДАННЫЕ',dateLabel(start)+' — 16 сентября 2026'],['Применены фильтры таблицы товаров','Площадка: '+market,'Категория: '+$('category').value,'Фильтр: '+$('risk').value],['Товар','Артикул','Площадка','Заказы','Оплачено','Возвраты','Выручка','Себестоимость','Комиссия','Логистика','Реклама','Хранение','Условный налог','Прибыль','Остаток','В пути','К поставке'],...all.map(p=>[p.name,p.sku,p.market,p.orders,p.paid,p.returns,p.revenue,p.purchase,p.commission,p.logistics,p.ads,p.storage,p.tax,p.profit,p.stock,p.incoming,p.reorder])],blob=new Blob(['\ufeff'+data.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='pult-detailed-demo.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('toast').textContent=`Скачан отчёт: ${all.length} товаров, все строки по выбранным фильтрам`;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',4000)};
document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelectorAll('nav a').forEach(x=>x.classList.toggle('active',x===a))}));render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});try{Promise.resolve(document.modelContext.registerTool({name:'set_demo_task_completed',title:'Отметить демонстрационную задачу',description:'Меняет статус одной из 12 задач до перезагрузки страницы.',inputSchema:{type:'object',properties:{taskIndex:{type:'integer',minimum:0,maximum:11},completed:{type:'boolean'}},required:['taskIndex','completed'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!Number.isInteger(input.taskIndex)||input.taskIndex<0||input.taskIndex>=tasks.length||typeof input.completed!=='boolean')throw new Error('Некорректная задача или статус');tasks[input.taskIndex].done=input.completed;renderTasks();return{title:tasks[input.taskIndex].title,completed:tasks[input.taskIndex].done,persistence:'until_reload'}}},{signal:lifecycle.signal})).catch(()=>{})}catch{}}
